60	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
61	        OwnerFieldsDto dto = (OwnerFieldsDto) body;
62	        if (!Boolean.TRUE.equals(dto.getSharesHousehold())) {
63	            String household = OwnerIdentityKey.householdId(dto.getLastName(), dto.getPostcode());
64	            boolean exists = clinicService.findAllOwners().stream()
65	                .anyMatch(o -> household.equals(OwnerIdentityKey.householdId(o.getLastName(), o.getPostcode())));
66	            if (exists) {
67	                throw new DuplicateHouseholdException();
68	            }
69	        }
70	        return body;
71	    }
